query:
SELECT 'projects' AS section, COUNT(*) AS count_value FROM geo_projects WHERE enterprise_name = '海豚知道';
SELECT 'questions' AS section, COUNT(*) AS count_value FROM geo_questions q JOIN geo_projects p ON q.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'ai_answers' AS section, COUNT(*) AS count_value FROM geo_ai_answers a JOIN geo_questions q ON a.question_id = q.id JOIN geo_projects p ON q.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'semantic_results' AS section, COUNT(*) AS count_value FROM geo_semantic_results s JOIN geo_ai_answers a ON s.answer_id = a.id JOIN geo_questions q ON a.question_id = q.id JOIN geo_projects p ON q.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'score_reports' AS section, COUNT(*) AS count_value FROM geo_score_reports r JOIN geo_projects p ON r.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'articles_total' AS section, COUNT(*) AS count_value FROM geo_articles a JOIN geo_projects p ON a.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'articles_published' AS section, COUNT(*) AS count_value FROM geo_articles a JOIN geo_projects p ON a.project_id = p.id WHERE p.enterprise_name = '海豚知道' AND a.status = '已发布';
SELECT 'publish_records' AS section, COUNT(*) AS count_value FROM geo_article_publish_records pr JOIN geo_articles a ON pr.article_id = a.id JOIN geo_projects p ON a.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'monitoring_records' AS section, COUNT(*) AS count_value FROM geo_article_monitoring m JOIN geo_articles a ON m.article_id = a.id JOIN geo_projects p ON a.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT 'client_reports' AS section, COUNT(*) AS count_value FROM geo_client_reports cr JOIN geo_projects p ON cr.project_id = p.id WHERE p.enterprise_name = '海豚知道';
SELECT a.id, a.title, a.article_type, a.status, a.quality_score, LENGTH(COALESCE(a.source_basis_json,'')) AS basis_len, LENGTH(COALESCE(a.fact_sources_json,'')) AS facts_len, LENGTH(COALESCE(a.consistency_check_json,'')) AS consistency_len, LENGTH(COALESCE(a.pre_publish_check_json,'')) AS prepublish_len, LENGTH(COALESCE(a.quotable_fragments_json,'')) AS quote_len FROM geo_articles a JOIN geo_projects p ON a.project_id = p.id WHERE p.enterprise_name = '海豚知道' ORDER BY a.id LIMIT 10;
SELECT pr.article_id, pr.platform, pr.publish_status, pr.public_url FROM geo_article_publish_records pr JOIN geo_articles a ON pr.article_id = a.id JOIN geo_projects p ON a.project_id = p.id WHERE p.enterprise_name = '海豚知道' ORDER BY pr.id LIMIT 5;
SELECT m.article_id, m.index_status, m.ai_mention_status, m.ai_recommend_status, LEFT(m.current_suggestion, 120) AS current_suggestion FROM geo_article_monitoring m JOIN geo_articles a ON m.article_id = a.id JOIN geo_projects p ON a.project_id = p.id WHERE p.enterprise_name = '海豚知道' ORDER BY m.id LIMIT 5;
SELECT cr.id, cr.report_title, cr.risk_note FROM geo_client_reports cr JOIN geo_projects p ON cr.project_id = p.id WHERE p.enterprise_name = '海豚知道' ORDER BY cr.id DESC LIMIT 3;

